blocks.text:
p.normal {
  font-style: normal;
}

p.italic {
  font-style: italic;
}

p.oblique {
  font-style: oblique;
}

p.normal {
  font-weight: normal;
}

p.light {

  font-weight: lighter;
}

p.thick {
  font-weight: bold;
}

p.thicker {
  font-weight: 900;
}

p.normal {
  font-variant: normal;
}

p.small {
  font-variant: small-caps;
}
